parameters.jsCode:
const data = $input.item.json.output || $input.item.json;
const original = $('Normalize Item').item.json;

const score =
  (data.relevancia_latam || 0) +
  (data.novedad || 0) +
  (data.urgencia || 0) +
  (data.credibilidad_fuente || 0) +
  (data.potencial_educativo || 0) +
  (data.potencial_viral || 0) +
  (data.fit_marca || 0) +
  (data.riesgo || 0);

let classification = 'discard';
if (score >= 70) classification = 'strong';
else if (score >= 50) classification = 'consider';

return {
  ...original,
  ...data,
  total_score: Math.round(score * 100) / 100,
  classification,
  signal_score: Math.round(score * 100) / 100
};

